use std::{env, fs, process};

struct Section {
    name: String,
    inherits: Option<String>,
    fields: Vec<(String, String)>,
}

fn fail(message: impl AsRef<str>) -> ! {
    eprintln!("{}", message.as_ref());
    process::exit(1);
}

fn parse_quoted(input: &str) -> Result<String, String> {
    if input.len() < 2 || !input.starts_with('"') || !input.ends_with('"') {
        return Err("expected a quoted value".to_owned());
    }
    let inner = &input[1..input.len() - 1];
    let mut output = String::new();
    let mut characters = inner.chars();
    while let Some(character) = characters.next() {
        if character != '\\' {
            if character == '"' {
                return Err("unescaped quote in value".to_owned());
            }
            output.push(character);
            continue;
        }
        let escaped = characters
            .next()
            .ok_or_else(|| "unfinished escape in value".to_owned())?;
        match escaped {
            '"' => output.push('"'),
            '\\' => output.push('\\'),
            'n' => output.push('\n'),
            'r' => output.push('\r'),
            't' => output.push('\t'),
            other => return Err(format!("unsupported escape '\\{}'", other)),
        }
    }
    Ok(output)
}

fn resolve_section(index: usize, sections: &[Section]) -> Result<Vec<(String, String)>, String> {
    let section = &sections[index];
    let mut resolved = Vec::new();

    if let Some(parent_name) = &section.inherits {
        let parent_index = sections
            .iter()
            .position(|candidate| candidate.name == *parent_name)
            .ok_or_else(|| {
                format!(
                    "section '{}' inherits unknown section '{}'",
                    section.name, parent_name
                )
            })?;
        let parent = &sections[parent_index];
        if parent.inherits.is_some() {
            return Err(format!(
                "section '{}' has an inheritance chain longer than one level",
                section.name
            ));
        }
        for (key, value) in &parent.fields {
            if key != "inherits" {
                resolved.push((key.clone(), value.clone()));
            }
        }
    }

    for (key, value) in &section.fields {
        if key == "inherits" {
            continue;
        }
        if let Some(existing) = resolved
            .iter_mut()
            .find(|(existing_key, _)| existing_key == key)
        {
            existing.1 = value.clone();
        } else {
            resolved.push((key.clone(), value.clone()));
        }
    }
    Ok(resolved)
}

fn main() {
    let path = match env::args().nth(1) {
        Some(path) => path,
        None => fail("missing input path"),
    };
    let input = match fs::read_to_string(&path) {
        Ok(input) => input,
        Err(error) => fail(format!("cannot read '{}': {}", path, error)),
    };

    let mut sections: Vec<Section> = Vec::new();
    let mut current: Option<usize> = None;

    for (line_number, raw_line) in input.lines().enumerate() {
        let line = raw_line.strip_suffix('\r').unwrap_or(raw_line).trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        if line.starts_with('[') {
            if !line.ends_with(']') || line.len() <= 2 {
                fail(format!("line {}: malformed section header", line_number + 1));
            }
            let name = line[1..line.len() - 1].trim();
            if name.is_empty() || name.contains('[') || name.contains(']') {
                fail(format!("line {}: malformed section header", line_number + 1));
            }
            if sections.iter().any(|section| section.name == name) {
                fail(format!("line {}: duplicate section '{}',", line_number + 1, name));
            }
            sections.push(Section {
                name: name.to_owned(),
                inherits: None,
                fields: Vec::new(),
            });
            current = Some(sections.len() - 1);
            continue;
        }

        let section_index = match current {
            Some(index) => index,
            None => fail(format!("line {}: field appears before a section", line_number + 1)),
        };
        let (key, raw_value) = match line.split_once('=') {
            Some(parts) => parts,
            None => fail(format!("line {}: expected key = value", line_number + 1)),
        };
        let key = key.trim();
        if key.is_empty() {
            fail(format!("line {}: empty field name", line_number + 1));
        }
        if sections[section_index]
            .fields
            .iter()
            .any(|(existing_key, _)| existing_key == key)
        {
            fail(format!(
                "duplicate field '{}' in section '{}'",
                key, sections[section_index].name
            ));
        }
        let value = match parse_quoted(raw_value.trim()) {
            Ok(value) => value,
            Err(error) => fail(format!("line {}: {}", line_number + 1, error)),
        };
        if key == "inherits" {
            sections[section_index].inherits = Some(value.clone());
        }
        sections[section_index]
            .fields
            .push((key.to_owned(), value));
    }

    if sections.is_empty() {
        fail("configuration has no sections");
    }

    let mut output = String::new();
    for (index, section) in sections.iter().enumerate() {
        let resolved = match resolve_section(index, &sections) {
            Ok(resolved) => resolved,
            Err(error) => fail(error),
        };
        for (key, value) in resolved {
            output.push_str(&section.name);
            output.push('.');
            output.push_str(&key);
            output.push('=');
            output.push_str(&value);
            output.push('\n');
        }
    }
    print!("{}", output);
}
